exigirLogin();$oid=(int)($_GET['oferta_id']??$_POST['oferta_id']??0);if(!$oid||!puedeGestionarOferta($oid)){http_response_code(403);die('No tienes acceso a esta asignación.');}$o=ofertaDetalle($oid);if(!$o){http_response_code(404);die('Asignación inexistente.');}
