  try{$sid=(int)($_POST['sesion_id']??0);$stmt=$conexion->prepare("SELECT s.*,COUNT(d.id) total,SUM(d.estado='presente') presentes,SUM(d.estado='ausente') ausentes,SUM(d.estado='atraso') atrasos,SUM(d.estado='justificado') justificados FROM asistencia_sesiones s LEFT JOIN asistencia_detalle d ON d.sesion_id=s.id WHERE s.id=? AND s.oferta_id=? GROUP BY s.id LIMIT 1");$stmt->bind_param('ii',$sid,$oid);$stmt->execute();$antes=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$antes)throw new Exception('Registro de asistencia no encontrado.');$stmt=$conexion->prepare('DELETE FROM asistencia_sesiones WHERE id=? AND oferta_id=?');$stmt->bind_param('ii',$sid,$oid);$stmt->execute();$stmt->close();registrarAuditoria('DELETE','Asistencia','asistencia_sesion',$sid,'Jornada de asistencia eliminada · '.$o['asignatura'].' · '.$antes['fecha'].'.',null,$antes,null,'exito',null,null,'critica');flash('success','Jornada de asistencia eliminada. Puedes volver a registrarla si fue necesario.');}catch(Throwable $e){flash('error','No se pudo eliminar: '.$e->getMessage());}redir('modulos/asistencia/historial.php?oferta_id='.$oid);
