$stmt=$conexion->prepare("SELECT s.id,s.fecha,s.tema,s.observaciones,COUNT(d.id) total,SUM(d.estado='presente') presentes,SUM(d.estado='ausente') ausentes,SUM(d.estado='atraso') atrasos,SUM(d.estado='justificado') justificados,CONCAT(u.apellidos,' ',u.nombres) registrado_por FROM asistencia_sesiones s LEFT JOIN asistencia_detalle d ON d.sesion_id=s.id JOIN usuarios u ON u.id=s.registrado_por WHERE s.oferta_id=? GROUP BY s.id,s.fecha,s.tema,s.observaciones,u.apellidos,u.nombres ORDER BY s.fecha DESC,s.id DESC");$stmt->bind_param('i',$oid);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
$tituloPagina='Historial de asistencia · '.$o['asignatura'];$subtituloPagina=$o['nivel'].' · '.$o['aula'].' '.$o['paralelo'].' · '.$o['periodo'];require __DIR__.'/../../partials/header.php';
